-- Governance lifecycle advances one legal state at a time; C3R3 cutover remains pending.
with advanced as ( update runtime_config_inventory_governance set status='CLASSIFIED',classified_by='v41-c3r2n-operational-classifier',classified_at=coalesce(classified_at,now()),reason='V41_C3R2N_REMAINING_AUTHORITY_OPERATIONAL_CONSUMER_CLOSURE typed runtime consumer classification completed',version=version+1 where configuration_key in ('admin.metrics-push-enabled','admin.metrics-push-interval-ms','admin.recent-event-limit','event.dedup.redis.lock-lease-seconds','event.dedup.redis.lock-wait-seconds','incident.summary.window','opendispatch.operational.metrics.refresh-ms','opendispatch.operational.slo.dispatch-oldest-age-seconds','opendispatch.operational.slo.reconciliation-oldest-age-seconds') and status='DISCOVERED' returning configuration_key,source_observation_hash ) insert into runtime_config_inventory_governance_events(configuration_key,event_type,from_status,to_status,actor,reason,source_observation_hash,detail_json) select configuration_key,'CLASSIFIED','DISCOVERED','CLASSIFIED','v41-c3r2n-operational-classifier','V41_C3R2N_REMAINING_AUTHORITY_OPERATIONAL_CONSUMER_CLOSURE typed runtime consumer classification completed',source_observation_hash,'{"stage":"V41_C3R2N_REMAINING_AUTHORITY_OPERATIONAL_CONSUMER_CLOSURE","cutover":"NOT_FINALIZED"}'::jsonb from advanced;
with advanced as ( update runtime_config_inventory_governance set status='OWNER_REVIEWED',owner_reviewed_by='remaining-operational-domain-owner',owner_reviewed_at=coalesce(owner_reviewed_at,now()),reason='V41_C3R2N_REMAINING_AUTHORITY_OPERATIONAL_CONSUMER_CLOSURE domain owner reviewed runtime semantics and validation bounds',version=version+1 where configuration_key in ('admin.metrics-push-enabled','admin.metrics-push-interval-ms','admin.recent-event-limit','event.dedup.redis.lock-lease-seconds','event.dedup.redis.lock-wait-seconds','incident.summary.window','opendispatch.operational.metrics.refresh-ms','opendispatch.operational.slo.dispatch-oldest-age-seconds','opendispatch.operational.slo.reconciliation-oldest-age-seconds') and status='CLASSIFIED' returning configuration_key,source_observation_hash ) insert into runtime_config_inventory_governance_events(configuration_key,event_type,from_status,to_status,actor,reason,source_observation_hash,detail_json) select configuration_key,'OWNER_REVIEWED','CLASSIFIED','OWNER_REVIEWED','remaining-operational-domain-owner','V41_C3R2N_REMAINING_AUTHORITY_OPERATIONAL_CONSUMER_CLOSURE domain owner reviewed runtime semantics and validation bounds',source_observation_hash,'{"stage":"V41_C3R2N_REMAINING_AUTHORITY_OPERATIONAL_CONSUMER_CLOSURE","cutover":"NOT_FINALIZED"}'::jsonb from advanced;
with advanced as ( update runtime_config_inventory_governance set status='ARCHITECTURE_APPROVED',architecture_approved_by='configuration-architecture-reviewer',architecture_approved_at=coalesce(architecture_approved_at,now()),reason='DB authority + Redis distribution + authenticated local snapshot architecture approved',version=version+1 where configuration_key in ('admin.metrics-push-enabled','admin.metrics-push-interval-ms','admin.recent-event-limit','event.dedup.redis.lock-lease-seconds','event.dedup.redis.lock-wait-seconds','incident.summary.window','opendispatch.operational.metrics.refresh-ms','opendispatch.operational.slo.dispatch-oldest-age-seconds','opendispatch.operational.slo.reconciliation-oldest-age-seconds') and status='OWNER_REVIEWED' returning configuration_key,source_observation_hash ) insert into runtime_config_inventory_governance_events(configuration_key,event_type,from_status,to_status,actor,reason,source_observation_hash,detail_json) select configuration_key,'ARCHITECTURE_APPROVED','OWNER_REVIEWED','ARCHITECTURE_APPROVED','configuration-architecture-reviewer','DB authority + Redis distribution + authenticated local snapshot architecture approved',source_observation_hash,'{"stage":"V41_C3R2N_REMAINING_AUTHORITY_OPERATIONAL_CONSUMER_CLOSURE","cutover":"NOT_FINALIZED"}'::jsonb from advanced;
with advanced as ( update runtime_config_inventory_governance set status='MIGRATION_READY',migration_authorized_by='v41-c3r2n-remaining-authority-operational-consumer-closure',migration_authorized_at=coalesce(migration_authorized_at,now()),reason='C3R2N typed runtime consumers implemented; Single Authority cutover remains pending',version=version+1 where configuration_key in ('admin.metrics-push-enabled','admin.metrics-push-interval-ms','admin.recent-event-limit','event.dedup.redis.lock-lease-seconds','event.dedup.redis.lock-wait-seconds','incident.summary.window','opendispatch.operational.metrics.refresh-ms','opendispatch.operational.slo.dispatch-oldest-age-seconds','opendispatch.operational.slo.reconciliation-oldest-age-seconds') and status='ARCHITECTURE_APPROVED' returning configuration_key,source_observation_hash ) insert into runtime_config_inventory_governance_events(configuration_key,event_type,from_status,to_status,actor,reason,source_observation_hash,detail_json) select configuration_key,'MIGRATION_READY','ARCHITECTURE_APPROVED','MIGRATION_READY','v41-c3r2n-remaining-authority-operational-consumer-closure','C3R2N typed runtime consumers implemented; Single Authority cutover remains pending',source_observation_hash,'{"stage":"V41_C3R2N_REMAINING_AUTHORITY_OPERATIONAL_CONSUMER_CLOSURE","cutover":"NOT_FINALIZED"}'::jsonb from advanced;
do $$ declare v_governance_ready integer; begin select count(*) into v_governance_ready from runtime_config_inventory_governance where configuration_key in ('admin.metrics-push-enabled','admin.metrics-push-interval-ms','admin.recent-event-limit','event.dedup.redis.lock-lease-seconds','event.dedup.redis.lock-wait-seconds','incident.summary.window','opendispatch.operational.metrics.refresh-ms','opendispatch.operational.slo.dispatch-oldest-age-seconds','opendispatch.operational.slo.reconciliation-oldest-age-seconds') and status='MIGRATION_READY' and classified_by is not null and owner_reviewed_by is not null and architecture_approved_by is not null and migration_authorized_by='v41-c3r2n-remaining-authority-operational-consumer-closure'; if v_governance_ready<>9 then raise exception 'C3R2N_GOVERNANCE_LIFECYCLE_INCOMPLETE expected=9 actual=%',v_governance_ready; end if; end $$;


do $$ declare v_ready integer; v_proposed integer; begin
select count(*) into v_ready from runtime_config_definitions where definition_key in ('admin.metrics-push-enabled','admin.metrics-push-interval-ms','admin.recent-event-limit','event.dedup.redis.lock-lease-seconds','event.dedup.redis.lock-wait-seconds','incident.summary.window','opendispatch.operational.metrics.refresh-ms','opendispatch.operational.slo.dispatch-oldest-age-seconds','opendispatch.operational.slo.reconciliation-oldest-age-seconds') and review_status='MIGRATION_READY' and migration_authorized=true and admin_editable=true;
if v_ready<>9 then raise exception 'C3R2N_ACTIVE_OPERATIONAL_CONSUMER_CLOSURE_INCOMPLETE expected=9 actual=%',v_ready; end if;
if exists(select 1 from runtime_config_definitions where definition_key in ('admin.cors-allowed-origin-patterns','admin.cors-allowed-origins','admin.cors-max-age-seconds','admin.machine-auth-enabled','admin.machine-web-socket-handshake-auth-enabled','admin.metrics-push-initial-delay-ms','aeg.enforcement-activation.cluster-node-stale-after','aeg.enforcement-activation.revision-sync-enabled','aeg.enforcement-activation.revision-sync-initial-delay-ms','aeg.enforcement-activation.revision-sync-interval-ms','aeg.enforcement-activation.task-list-search-pilot-enabled','aeg.enforcement-activation.wave0-read-pilot-enabled','audit.persistence-enabled','core.security.admin.bootstrap.allowed-tenant-ids','core.security.admin.bootstrap.default-tenant-id','core.security.admin.bootstrap.display-name','core.security.admin.bootstrap.enabled','core.security.admin.bootstrap.roles','core.security.admin.bootstrap.user-id','core.security.admin.bootstrap.username','core.security.admin.cookie-same-site','core.security.admin.cookie-secure','core.security.admin.enabled','core.security.admin.session-cookie-name','core.security.admin.session-redis-namespace','core.security.admin.session-timeout','core.security.internal.audit-log-enabled','core.security.internal.enabled','core.security.internal.permit-actuator-health-info','core.security.internal.protect-api-mutations','event.dedup.redis.key-prefix','logging.level.com.opensocket.aievent.gateway.netty','logging.level.root','management.endpoint.health.probes.enabled','management.endpoint.health.show-details','management.endpoints.web.exposure.include','management.health.livenessstate.enabled','management.health.mail.enabled','management.health.readinessstate.enabled','management.info.build.enabled','management.info.env.enabled','management.metrics.tags.application','management.metrics.tags.service','management.opentelemetry.resource-attributes.deployment.environment','management.opentelemetry.resource-attributes.deployment.environment.name','management.opentelemetry.resource-attributes.service.name','management.opentelemetry.resource-attributes.service.namespace','management.opentelemetry.resource-attributes.service.version','management.opentelemetry.tracing.export.otlp.compression','management.opentelemetry.tracing.export.otlp.connect-timeout','management.opentelemetry.tracing.export.otlp.endpoint','management.opentelemetry.tracing.export.otlp.headers.Authorization','management.opentelemetry.tracing.export.otlp.timeout','management.opentelemetry.tracing.export.otlp.transport','management.opentelemetry.tracing.export.schedule-delay','management.opentelemetry.tracing.export.timeout','management.otlp.metrics.export.compression-mode','management.otlp.metrics.export.connect-timeout','management.otlp.metrics.export.enabled','management.otlp.metrics.export.headers.Authorization','management.otlp.metrics.export.read-timeout','management.otlp.metrics.export.step','management.otlp.metrics.export.url','management.tracing.enabled','management.tracing.export.otlp.enabled','management.tracing.propagation.consume','management.tracing.propagation.produce','management.tracing.sampling.probability','opendispatch.operational.schedulers.dispatch.pool-size','opendispatch.operational.schedulers.maintenance.pool-size','opendispatch.operational.schedulers.projection.pool-size','opendispatch.operational.schedulers.reconciliation.pool-size','ui-capability.access-request-enabled','ui-capability.enabled','ui-capability.page-bootstrap-enabled','ui-capability.projection-api-enabled','ui-capability.projection.maximum-cache-entries','ui-capability.projection.maximum-ttl') and (migration_authorized=true or admin_editable=true or review_status<>'RETIRED')) then raise exception 'C3R2N_AUTHORITY_RECLASSIFICATION_FAILED'; end if;
select count(*) into v_proposed from runtime_config_definitions where authority_class='RUNTIME_TUNABLE' and review_status='PROPOSED';
if v_proposed<>0 then raise exception 'C3R2N_RUNTIME_TARGET_CLASSIFICATION_NOT_CLOSED proposed=%',v_proposed; end if;
if exists(select 1 from runtime_config_inventory_governance where configuration_key in ('admin.metrics-push-enabled','admin.metrics-push-interval-ms','admin.recent-event-limit','event.dedup.redis.lock-lease-seconds','event.dedup.redis.lock-wait-seconds','incident.summary.window','opendispatch.operational.metrics.refresh-ms','opendispatch.operational.slo.dispatch-oldest-age-seconds','opendispatch.operational.slo.reconciliation-oldest-age-seconds') and status in ('MIGRATED','LEGACY_RETIRED')) then raise exception 'C3R2N_PREMATURE_SINGLE_AUTHORITY_CUTOVER'; end if;
end $$;
